(function executeRule(current, previous) {

    if (current.operation() != 'insert') return;

    var groupByCategory = {
        'network':  'Network Support',
        'hardware': 'Desktop Support'
    };

    var groupName = groupByCategory[current.category.toString()];
    if (groupName) {
        var group = new GlideRecord('sys_user_group');
        group.addQuery('name', groupName);
        group.query();
        if (group.next()) {
            current.assignment_group = group.sys_id;
        }
    }

})(current, previous);

(function executeRule(current, previous) {

    var justEscalated = (current.priority == 1 &&
        previous.priority != 1);
    if (!justEscalated) return;

    var agent = new GlideRecord('sys_user');
    if (!agent.get(current.assigned_to)) return;

    var manager = new GlideRecord('sys_user');
    if (manager.get(agent.manager)) {
        gs.eventQueue('incident.priority.escalated',
            current, manager.sys_id, current.number);
    }

})(current, previous);
